use gtkg_core::{CallContext,TransportKind,EffectPolicy,v04::{source,artifact,analysis}};
use gtkg_protocol::v04::{ArtifactPayload,Revision};
use std::{fs,io::Write,process::{Command,Stdio},path::Path};
fn git(p:&Path,args:&[&str])->String{let o=Command::new("git").arg("-C").arg(p).args(args).output().expect("git");assert!(o.status.success());String::from_utf8(o.stdout).expect("utf8").trim().into()}
#[test]fn go_module_mapping_is_derived_from_frozen_source_data_not_worktree(){let t=tempfile::tempdir().expect("temp");let repo=t.path().join("repo");let work=t.path().join("work");fs::create_dir(&repo).expect("repo");fs::create_dir(&work).expect("work");git(&repo,&["init","-q"]);let files=[("go.mod","module example.test/agent\n\ngo 1.22\n"),("main.go","package main\nfunc main(){}\n"),("internal/session/session.go","package history\nfunc Restore(){}\n"),("tools/go.mod","module example.test/tools\n"),("tools/tool.go","package tools\nfunc Run(){}\n")];let mut input=Vec::new();for(i,(_,s))in files.iter().enumerate(){input.extend(format!("blob\nmark :{}\ndata {}\n{}\n",i+1,s.len(),s).as_bytes())}input.extend(b"commit refs/heads/main\ncommitter Fixture <fixture@example.invalid> 0 +0000\ndata 3\nqk\n\n");for(i,(p,_))in files.iter().enumerate(){input.extend(format!("M 100644 :{} {}\n",i+1,p).as_bytes())}input.push(b'\n');let mut child=Command::new("git").arg("-C").arg(&repo).args(["fast-import","--quiet"]).stdin(Stdio::piped()).spawn().expect("import");child.stdin.take().expect("stdin").write_all(&input).expect("write");assert!(child.wait().expect("wait").success());let ctx=CallContext::restricted(TransportKind::Test,vec![work.clone(),repo.clone()],EffectPolicy::WorkspaceWrite).expect("ctx");let req=source::SourceCaptureRequest{repository_id:"fixture".into(),source_root:repo.clone(),source_commit:git(&repo,&["rev-parse","main"]),expected_tree:git(&repo,&["rev-parse","main^{tree}"]),output_path:work.join("archive"),policy:source::ScopePolicy::default()};source::capture(&req).expect("capture");fs::write(repo.join("go.mod"),"module wrong.invalid/dirty\n").expect("dirty");let r=artifact::reference(&ctx,&work,&req.output_path.join(source::LEDGER_FILE)).expect("ref");let result=analysis::plan(&ctx,&ArtifactPayload{payload_revision:Revision::R1,workspace_root:work.clone(),artifact_ref:r}).expect("plan");let r=serde_json::from_value(result["artifact_ref"].clone()).expect("plan ref");let(p,_):(analysis::AnalysisPlan,_)=artifact::read(&ctx,&work,&r).expect("read");assert_eq!(p.context.import_modules.get("example.test/agent/internal/session").map(String::as_str),Some("internal/session"));assert_eq!(p.context.import_modules.get("example.test/tools").map(String::as_str),Some("tools"));assert!(!p.context.import_modules.keys().any(|k|k.contains("wrong.invalid")));assert!(!p.context.import_modules.contains_key("example.test/agent/tools"));}
